onChange.script:

if origin != 'Browser': return
for itemUnit in system.dataset.toPyDataSet(self.view.custom.itemUnits):
	if self.props.value == itemUnit['itemUnitId']:
		self.view.custom.lotEventInfo['itemUnitName'] = itemUnit['itemUnitName']
		break

return


system.perspective.print("itemTreeSelector value changed by %s - selectedItems %s"%(origin,self.props.params.values.selection))

if len(self.props.params.values.selection) > 0: 
	self.view.custom.lotEventInfo['itemId'] = self.props.params.values.selection[0].value['itemId']
	if self.view.custom.lotEventInfo['assetId'] is not None:
		itemAssetInfo = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.item.getAssetItems({'assetId': self.view.custom.lotEventInfo['assetId'] , 'itemId': self.view.custom.lotEventInfo['itemId']}), 0)
		if self.view.custom.lotEventInfo['itemSourceName'] == 'input':
			self.view.custom.lotEventInfo['itemUnitId'] = itemAssetInfo['infeedUnitId']
		if self.view.custom.lotEventInfo['itemSourceName'] == 'output':
			self.view.custom.lotEventInfo['itemUnitId'] = itemAssetInfo['outfeedUnitId']

return

transforms.code:
def safeKey(x):
	label = x['label']
	try:
		return (0, int(label))  # numeric sort
	except ValueError:
		return (1, label)       # string sort after numbers

assets = system.kanoa.asset.getAssets({'assetTypeName': 'truck'})
return sorted([{'label': asset['assetName'], 'value': asset['assetId']} for asset in assets], key=safeKey)

